    {"ID": 150, "category": "Technology", "specialty": "Data Science", "Difficulty": "Hard", "Question": "What are the different types of recommendation systems?", "Answer": "Recommendation systems include collaborative filtering, content-based filtering, and hybrid methods to suggest relevant items to users."},
    {"ID": 151, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is data observability?", "Answer": "Data observability refers to monitoring, tracking, and troubleshooting data quality and lineage in a system."},
    {"ID": 152, "category": "Technology", "specialty": "Data Science", "Difficulty": "Hard", "Question": "What is active learning in machine learning?", "Answer": "Active learning is a technique where the model selects the most informative data points for labeling to improve learning efficiency."},
    {"ID": 153, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is concept drift in machine learning?", "Answer": "Concept drift occurs when the statistical properties of the target variable change over time, affecting model accuracy."},
