    {"ID": 165, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is an early stopping technique in training neural networks?", "Answer": "Early stopping halts training when the model's performance stops improving on validation data, preventing overfitting."},
    {"ID": 166, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is explainable AI (XAI)?", "Answer": "Explainable AI aims to make machine learning models more transparent and interpretable for users."},
    {"ID": 167, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is an imbalanced dataset, and how do you handle it?", "Answer": "An imbalanced dataset has an unequal distribution of class labels, and it can be handled using techniques like resampling, SMOTE, and cost-sensitive learning."},
    {"ID": 168, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is reinforcement learning in data science?", "Answer": "Reinforcement learning is a type of machine learning where an agent learns optimal behavior through rewards and penalties."},
