    {"ID": 204, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is semi-supervised anomaly detection?", "Answer": "Semi-supervised anomaly detection trains on normal data with little or no labeled anomalies to detect outliers."},
    {"ID": 205, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is the importance of a data schema?", "Answer": "A data schema defines the structure and relationships of a database, ensuring organized data storage and retrieval."},
