    {"ID": 207, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is a multicollinearity problem in regression?", "Answer": "Multicollinearity occurs when independent variables in a regression model are highly correlated, leading to unstable coefficients."},
    {"ID": 208, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is the bias in natural language processing (NLP)?", "Answer": "Bias in NLP refers to systematic errors in language models due to biased training data, affecting fairness and accuracy."},
    {"ID": 209, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is an adversarial example?", "Answer": "An adversarial example is an input intentionally altered to mislead a machine learning model into making incorrect predictions."},
    {"ID": 210, "category": "Technology", "specialty": "Data Science", "Difficulty": "Hard", "Question": "What is an auto-regressive model?", "Answer": "An auto-regressive model predicts future values in a time series based on past observations."},
    {"ID": 211, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is data binning?", "Answer": "Data binning is the process of grouping continuous values into discrete intervals to reduce noise and improve data analysis."},
