    {"ID": 217, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is differential evolution in optimization?", "Answer": "Differential evolution is an optimization technique that iteratively improves solutions using evolutionary algorithms."},
    {"ID": 218, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is a surrogate model?", "Answer": "A surrogate model is a simplified approximation of a complex system used to accelerate optimization."},
    {"ID": 219, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is data spillage in machine learning?", "Answer": "Data spillage occurs when test data leaks into the training set, leading to unrealistic performance estimates."},
    {"ID": 220, "category": "Technology", "specialty": "Data Science", "Difficulty": "Hard", "Question": "What is knowledge graph embedding?", "Answer": "Knowledge graph embedding represents entities and relationships in a graph as numerical vectors for machine learning tasks."},
    {"ID": 221, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is model stacking?", "Answer": "Model stacking is an ensemble technique where multiple models' outputs are combined using a meta-model."},
    {"ID": 222, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is a Markov blanket?", "Answer": "A Markov blanket of a node in a Bayesian network consists of its parents, children, and co-parents, defining its conditional independence."},
    {"ID": 223, "category": "Technology", "specialty": "Data Science", "Difficulty": "Hard", "Question": "What is reinforcement learning with policy gradient?", "Answer": "Policy gradient methods optimize reinforcement learning policies by directly adjusting action probabilities."},
    {"ID": 224, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is evolutionary computing?", "Answer": "Evolutionary computing is a subset of artificial intelligence inspired by biological evolution, using algorithms like genetic programming."},
    {"ID": 225, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is a probabilistic graphical model?", "Answer": "A probabilistic graphical model represents probabilistic relationships between variables using graphs, such as Bayesian and Markov networks."},
    {"ID": 226, "category": "Technology", "specialty": "Data Science", "Difficulty": "Hard", "Question": "What is continual learning?", "Answer": "Continual learning enables models to learn new tasks over time without forgetting previously learned tasks."},
    {"ID": 227, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is the importance of hashing in data science?", "Answer": "Hashing is used to efficiently map data to a fixed-size representation, useful in indexing, security, and feature engineering."},
    {"ID": 228, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is the difference between structured prediction and standard classification?", "Answer": "Structured prediction models complex outputs with interdependent variables, while standard classification predicts independent labels."},
    {"ID": 229, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is the difference between rule-based systems and machine learning models?", "Answer": "Rule-based systems use predefined logical rules, while machine learning models learn patterns from data."},
    {"ID": 230, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is the importance of synthetic minority over-sampling (SMOTE)?", "Answer": "SMOTE generates synthetic examples for the minority class to balance class distribution in imbalanced datasets."},
    {"ID": 231, "category": "Technology", "specialty": "Data Science", "Difficulty": "Hard", "Question": "What is the Wasserstein distance, and how is it used in machine learning?", "Answer": "Wasserstein distance measures differences between probability distributions, used in generative adversarial networks (GANs)."},
    {"ID": 232, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is an inductive bias in machine learning?", "Answer": "Inductive bias refers to the assumptions a model makes to generalize from training data to unseen data."},
    {"ID": 233, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is the purpose of dropout in neural networks?", "Answer": "Dropout randomly disables neurons during training to prevent overfitting and improve generalization."},
    {"ID": 234, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is transfer entropy in time series analysis?", "Answer": "Transfer entropy measures the directional information transfer between two time series variables."},
    {"ID": 235, "category": "Technology", "specialty": "Data Science", "Difficulty": "Medium", "Question": "What is anomaly detection in cybersecurity?", "Answer": "Anomaly detection in cybersecurity identifies unusual behavior in network traffic or system logs to detect potential attacks."},
    {"ID": 236, "category": "Technology", "specialty": "Data Science", "Difficulty": "Hard", "Question": "What is self-normalizing neural networks (SNNs)?", "Answer": "Self-normalizing neural networks use activation functions like SELU to maintain stable activations during training."},
